import { useState, useEffect } from 'react';
import { useNavigate, Link, Routes, Route } from 'react-router-dom';
import 'bootstrap/dist/css/bootstrap.min.css';
import '@fortawesome/fontawesome-free/css/all.min.css';

import Home from './Home';
import Students from './Students';
import Courses from './Courses';
import Questions from './Questions';

export default function AdminDashboard() {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState('dashboard');

  useEffect(() => {
    const path = window.location.pathname;
    if (path === '/admin') setActiveTab('dashboard');
    else if (path === '/admin/students') setActiveTab('students');
    else if (path === '/admin/courses') setActiveTab('courses');
    else if (path === '/admin/questions') setActiveTab('questions');
  }, []);

  const handleLogout = () => {
    localStorage.removeItem('token');
    navigate('/login');
  };

  const menu = [
    { id: 'dashboard', label: 'Home', icon: 'fa-home', path: '/admin' },
    { id: 'students', label: 'Students', icon: 'fa-users', path: '/admin/students' },
    { id: 'courses', label: 'Courses', icon: 'fa-book', path: '/admin/courses' },
    { id: 'questions', label: 'Questions', icon: 'fa-question-circle', path: '/admin/questions' }
  ];

  return (
    <div style={{ display: 'flex', minHeight: '100vh', background: '#f8fafc' }}>

      {/* SIDEBAR */}
      <aside style={{
        width: '240px',
        background: '#0f172a',
        color: '#cbd5f5',
        padding: '20px 0',
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'space-between'
      }}>

        <div>
          {/* Logo */}
          <div style={{ textAlign: 'center', marginBottom: '30px' }}>
            <img src="/logo.png" style={{ width: '70px', borderRadius: '50%' }} />
            <h6 style={{ marginTop: '10px', color: '#fff', fontWeight: 500 }}>
              Admin Panel
            </h6>
          </div>

          {/* Menu */}
          {menu.map(item => (
            <Link
              key={item.id}
              to={item.path}
              onClick={() => setActiveTab(item.id)}
              style={{
                display: 'flex',
                alignItems: 'center',
                padding: '12px 20px',
                fontSize: '15px',
                color: activeTab === item.id ? '#fff' : '#94a3b8',
                background: activeTab === item.id ? '#1e293b' : 'transparent',
                borderLeft: activeTab === item.id ? '3px solid #3b82f6' : '3px solid transparent',
                textDecoration: 'none',
                transition: '0.2s'
              }}
              onMouseEnter={e => {
                if (activeTab !== item.id) e.currentTarget.style.background = '#1e293b';
              }}
              onMouseLeave={e => {
                if (activeTab !== item.id) e.currentTarget.style.background = 'transparent';
              }}
            >
              <i className={`fas ${item.icon}`} style={{ marginRight: '12px' }}></i>
              {item.label}
            </Link>
          ))}
        </div>

        {/* Footer */}
        <div style={{ padding: '0 20px' }}>
          <button
            onClick={handleLogout}
            style={{
              width: '100%',
              padding: '10px',
              background: '#ef4444',
              border: 'none',
              color: '#fff',
              borderRadius: '8px',
              fontSize: '14px'
            }}
          >
            Logout
          </button>
        </div>

      </aside>

      {/* MAIN */}
      <main style={{ flex: 1, padding: '30px' }}>

        {/* HEADER */}
        <div style={{
          marginBottom: '25px'
        }}>
          <h3 style={{ margin: 0, fontWeight: 600, color: '#0f172a' }}>
            Admin Dashboard
          </h3>
          <p style={{ margin: '5px 0 0', color: '#64748b', fontSize: '14px' }}>
            Manage your online quiz platform efficiently
          </p>
        </div>

        {/* CONTENT */}
        <div style={{
          background: '#ffffff',
          borderRadius: '12px',
          padding: '25px',
          boxShadow: '0 6px 25px rgba(0,0,0,0.05)'
        }}>
          <Routes>
            <Route index element={<Home />} />
            <Route path="students" element={<Students />} />
            <Route path="courses" element={<Courses />} />
            <Route path="questions" element={<Questions />} />
          </Routes>
        </div>

      </main>
    </div>
  );
}
